<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { Plus, ArrowUpRight, Search, ArrowLeft, Target, Check, BookOpen, Calendar, Pencil, ArrowRight } from 'lucide-vue-next'
import { api,post,patch,dateText,today } from '../api'
import Modal from '../components/Modal.vue'
import EmptyState from '../components/EmptyState.vue'
const route=useRoute(),router=useRouter(),students=ref<any[]>([]),report=ref<any>(null),error=ref(''),search=ref(''),showForm=ref(false),showPlan=ref(false),saving=ref(false)
const form=ref<any>({name:'',grade:'初三',textbook:'人教版',goal:'',notes:''})
const plan=ref({title:'',goal:'',due_date:today()})
const filtered=computed(()=>students.value.filter(s=>(s.name+s.grade).includes(search.value)))
async function load(){try{if(route.params.id)report.value=await api(`students/${route.params.id}/report/`);else students.value=await api('students/')}catch(e:any){error.value=e.message}}
onMounted(load)
async function save(){saving.value=true;try{if(form.value.id)await patch(`students/${form.value.id}/`,form.value);else await post('students/',form.value);showForm.value=false;await load()}catch(e:any){error.value=e.message}finally{saving.value=false}}
async function addPlan(){try{await post('plans/',{...plan.value,student:route.params.id});showPlan.value=false;await load()}catch(e:any){error.value=e.message}}
async function done(p:any){try{await patch(`plans/${p.id}/`,{completed:!p.completed});await load()}catch(e:any){error.value=e.message}}
</script>
<template><div v-if="!route.params.id" class="page-heading"><div><p class="eyebrow">STUDENTS</p><h1>每位学生，都有自己的轨迹<span class="heading-dot">.</span></h1><p class="subtitle">资料、练习与进步，在这里连成一条线。</p></div><button class="button primary" @click="showForm=true"><Plus :size="18"/>添加学生</button></div><div v-else class="page-heading"><div><RouterLink to="/students" class="back-link"><ArrowLeft :size="15"/>学生档案</RouterLink><h1>{{report?.student.name||'学生档案'}}<span class="heading-dot">.</span></h1><p class="subtitle">{{report?.student.grade}} · {{report?.student.textbook}}</p></div><div class="inline"><button v-if="report" class="button secondary" @click="form={...report.student};showForm=true"><Pencil :size="16"/>编辑档案</button><button class="button primary" @click="showPlan=true"><Plus :size="17"/>添加学习计划</button></div></div><div v-if="error" class="notice danger" role="alert">{{error}}</div>
 <template v-if="!route.params.id"><div class="toolbar"><div class="search-field"><Search :size="17"/><input v-model="search" placeholder="搜索学生姓名或年级" aria-label="搜索学生"/></div><span class="muted small">共 {{students.length}} 位学生</span></div><div class="student-grid"><RouterLink v-for="(s,index) in filtered" :key="s.id" :to="'/students/'+s.id" class="student-card"><div class="student-card-top"><span class="student-avatar" :class="['mint','peach','lavender'][index%3]">{{s.name.slice(-2)}}</span><ArrowUpRight :size="19"/></div><h2>{{s.name}}<span v-if="s.archived" class="tag">已归档</span></h2><p class="muted">{{s.grade||'年级未填写'}} · {{s.textbook||'教材未填写'}}</p><div class="student-goal"><Target :size="16"/><p>{{s.goal||'下一步，设置一个学习目标'}}</p></div><footer>查看学习档案<ArrowRight :size="16"/></footer></RouterLink></div><EmptyState v-if="!filtered.length" title="建立第一份学生档案" text="从学习目标开始，持续记录每一次作答。"/></template>
 <template v-else-if="report"><div class="profile-grid"><section class="panel"><header class="panel-heading"><h2>当前学习目标</h2><Target :size="20"/></header><p class="profile-goal">{{report.student.goal||'尚未设置学习目标'}}</p><p class="muted">{{report.student.notes||'暂无教学备注'}}</p></section><section class="panel"><header class="panel-heading"><h2>知识点表现</h2><BookOpen :size="20"/></header><div v-for="(stats,tag) in report.knowledge" :key="tag" class="knowledge-row"><div><strong>{{tag}}</strong><span>{{stats.attempts}} 次作答 · {{stats.wrong}} 次失分</span></div><div class="progress-bar"><i :style="{width:(1-stats.wrong/stats.attempts)*100+'%'}"></i></div></div><p v-if="!Object.keys(report.knowledge).length" class="muted">完成批改后，将根据实际作答展示知识点表现。</p></section></div>
 <section class="panel"><header class="panel-heading"><div><h2>作业与测试时间线</h2><p>完整测试定分后展示总分；零散错题仅记录逐题表现。</p></div></header><div v-if="report.timeline.length" class="table-scroll"><table><thead><tr><th>测试日期</th><th>作业 / 测试</th><th>批改进度</th><th>成绩</th><th></th></tr></thead><tbody><tr v-for="record in report.timeline" @click="router.push('/grading/'+record.id)"><td>{{record.date}}</td><td><strong>{{record.title}}</strong><span v-if="record.fragment" class="tag">零散错题</span></td><td>{{record.reviewed}} / {{record.count}}</td><td>{{record.score===null?'待完成 / 不计总分':record.score+' / '+record.maximum}}</td><td><ArrowUpRight :size="17"/></td></tr></tbody></table></div><EmptyState v-else title="等待第一份学习记录" text="录入学生作业或测试，开始记录学习轨迹。"/></section>
 <section class="panel"><header class="panel-heading"><h2>学习计划</h2></header><div v-for="p in report.plans" :key="p.id" class="todo"><button class="todo-check" :class="{checked:p.completed}" aria-label="切换计划完成状态" @click="done(p)"><Check v-if="p.completed" :size="14"/></button><div><strong :class="{struck:p.completed}">{{p.title}}</strong><p>{{p.goal}} · {{p.due_date||'未设置日期'}}</p></div></div><p v-if="!report.plans.length" class="muted padded">暂无计划，添加下一次课的重点。</p></section></template>
 <Modal v-if="showForm" :title="form.id?'编辑学生档案':'添加学生'" @close="showForm=false"><form @submit.prevent="save"><label>学生姓名 / 代号<input v-model="form.name" required maxlength="80"/></label><div class="form-grid"><label>年级<select v-model="form.grade"><option v-for="grade in ['初一','初二','初三','高一','高二','高三']">{{grade}}</option></select></label><label>教材版本<input v-model="form.textbook"/></label></div><label>学习目标<textarea v-model="form.goal" rows="3" placeholder="希望在哪些方面取得进步？"/></label><label>教学备注<textarea v-model="form.notes" rows="3"/></label><label v-if="form.id" class="check-row"><input v-model="form.archived" type="checkbox"/>归档学生（保留历史记录）</label><button class="button primary full" :disabled="saving">{{saving?'保存中…':'保存学生档案'}}</button></form></Modal>
 <Modal v-if="showPlan" title="添加学习计划" @close="showPlan=false"><form @submit.prevent="addPlan"><label>计划标题<input v-model="plan.title" required placeholder="如：二次函数专项复测"/></label><label>目标与安排<textarea v-model="plan.goal" rows="3"/></label><label>计划日期<input v-model="plan.due_date" type="date" required/></label><button class="button primary full">保存计划</button></form></Modal>
</template>
